WITH metrics AS (SELECT id, rating, LAST_VALUE(city, TRUE) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_city, SUM(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_rating FROM suppliers WHERE rating >= 3.9) SELECT CASE WHEN rating >= 3.7 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, ROUND(AVG(cumulative_rating), 2) AS avg_cumulative_rating, PERCENTILE_APPROX(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, APPROX_PERCENTILE(rating, 0.9) AS rating_p90, STDDEV_SAMP(rating) AS rating_stddev, COUNT(*) AS event_count FROM metrics GROUP BY CASE WHEN rating >= 3.7 THEN 'LARGE' ELSE 'SMALL' END HAVING rating_p90 > 0 ORDER BY event_count;
